//! A store.
use std::collections::HashMap;

/// Keys and values.
pub struct Store<K, V> {
    items: HashMap<K, V>,
    pub(crate) hits: u64,
}

impl<K: std::hash::Hash + Eq, V> Store<K, V> {
    pub fn new() -> Self { Self { items: HashMap::new(), hits: 0 } }
    pub fn get(&mut self, k: &K) -> Option<&V> { self.hits += 1; self.items.get(k) }
    pub(crate) fn clear(&mut self) { self.items.clear() }
    fn evict(&mut self) {}
}

impl<K, V> Drop for Store<K, V> { fn drop(&mut self) {} }

pub trait Backend {
